#include "ConfigManager.h"

ConfigManager::ConfigManager()
{
    cfg.ssid = "";
    cfg.password = "";

    cfg.callsign = "";
    cfg.authkey = "";

    cfg.host = DEFAULT_DAPNET_HOST;
    cfg.port = DEFAULT_DAPNET_PORT;

}

ConfigManager::~ConfigManager()
{
    prefs.end();

}

bool ConfigManager::begin()
{
    Serial.println();
    Serial.println("Start ConfigManager...");

    if( !prefs.begin(CONFIG_NAMESPACE, false) )
    {
        Serial.println("Preferences could not be opened.");

        return false;
    }

    return load();
    
}

bool ConfigManager::load()
{
    cfg.ssid     = prefs.getString("ssid", "");
    cfg.password = prefs.getString("pwd", "");
    cfg.callsign = prefs.getString("call", "");
    cfg.authkey  = prefs.getString("auth", "");
    cfg.host     = prefs.getString("host", DEFAULT_DAPNET_HOST);
    cfg.port     = prefs.getUShort("port", DEFAULT_DAPNET_PORT);

    // Check plausibility
    if( cfg.host.isEmpty() )
    {
        cfg.host = DEFAULT_DAPNET_HOST;
    }

    if( cfg.port == 0 )
    {
        cfg.port = DEFAULT_DAPNET_PORT;
    }

    Serial.println("Configuration loaded.");

    printConfig();

    return true;
    
}

bool ConfigManager::save()
{
    Serial.println();
    Serial.println("Saving configuration...");

    bool ok = true;

    ok &= prefs.putString("ssid", cfg.ssid);
    ok &= prefs.putString("pwd",  cfg.password);
    ok &= prefs.putString("call", cfg.callsign);
    ok &= prefs.putString("auth", cfg.authkey);
    ok &= prefs.putString("host", cfg.host);
    ok &= prefs.putUShort("port", cfg.port);

    if( ok )
    {
        Serial.println("Configuration saved.");
    }
    else
    {
        Serial.println("Error while saving.");
    }

    return ok;
    
}

void ConfigManager::reset()
{
    Serial.println();
    Serial.println("Factory reset.");

    prefs.clear();

    cfg.ssid     = "";
    cfg.password = "";
    cfg.callsign = "";
    cfg.authkey  = "";
    cfg.host     = DEFAULT_DAPNET_HOST;
    cfg.port     = DEFAULT_DAPNET_PORT;

    save();
    
}

bool ConfigManager::isConfigured()
{
    if( cfg.ssid.isEmpty() )
    {
        return false;
    }

    if( cfg.callsign.isEmpty() )
    {
        return false;
    }

    if( cfg.authkey.isEmpty() )
    {
        return false;
    }

    return true;
    
}

void ConfigManager::printConfig()
{
    Serial.println();
    Serial.println("===== Configuration =====");
    Serial.print("SSID      : "); Serial.println(cfg.ssid);
    Serial.print("CALLSIGN  : "); Serial.println(cfg.callsign);
    Serial.print("AUTHKEY   : ");
    
    if( cfg.authkey.length())
    {
        Serial.println("*** present ***");
    }
    else
    {
        Serial.println("<empty>");
    }

    Serial.print("HOST      : "); Serial.println(cfg.host);
    Serial.print("PORT      : "); Serial.println(cfg.port);
    Serial.println("=========================");
    
}
